/* AdminMoim_SQL.selectAdminMoimLocateList */ SELECT LOCATE_ID , LOCATE_NM , LOCATE_POST_CD , LOCATE_ADDRESS , LOCATE_D_ADDRESS , LOCATE_CN , LOCATE_USE_YN , LOCATE_DEL_YN , REG_ID , REG_DT , UPD_ID , UPD_DT FROM TB_MOIM_LOCATE_INFO WHERE 1=1 AND LOCATE_DEL_YN = 'N'
